import { AfterViewInit, Component, Input, OnInit, ViewChild, ChangeDetectorRef } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { Observable, ReplaySubject } from 'rxjs';
import { filter } from 'rxjs/operators';
import { ListColumn } from '../../../../src/@fury/shared/list/list-column.model';
import { RoleCreateUpdateComponent } from './role-create-update/role-create-update.component';
import { RolService } from '../../services/role.service';
import { ToastService } from 'src/app/shared/toast/toast.service';
import { LoaderService } from '../../shared/loader/loader.service';
import { Role } from '../roles/role-create-update/role.model'
import { PAGE_SIZE_OPTIONS } from '../../shared/const';
import { AuthService } from '../../services/auth.service'

@Component({
  selector: 'fury-roles',
  templateUrl: './roles.component.html',
  styleUrls: ['./roles.component.scss']
})
export class RolesComponent implements OnInit, AfterViewInit {

  pageSize = 5;
  pageSizeOptions = PAGE_SIZE_OPTIONS;

  subject$: ReplaySubject<Role[]> = new ReplaySubject<Role[]>(1);
  data$: Observable<Role[]> = this.subject$.asObservable();
  roles: Role[];

  @Input()
  columns: ListColumn[] = [
    { name: 'id Rol', property: 'id_rol', visible: false, isModelProperty: true },
    { name: 'Nombre Rol', property: 'name_rol', visible: true, isModelProperty: true },
    { name: 'Descripción', property: 'description', visible: true, isModelProperty: true },
    { name: 'Fraccionamiento', property: 'id_fraccionamiento', visible: false, isModelProperty: true },
    { name: 'Acciones', property: 'actions', visible: true }
  ] as ListColumn[];



  dataSource: MatTableDataSource<Role> | null;

  @ViewChild(MatPaginator, { static: true }) paginator: MatPaginator;
  @ViewChild(MatSort, { static: true }) sort: MatSort;

  constructor(
    private dialog: MatDialog,
    private roleService: RolService,
    private toast: ToastService,
    private loader: LoaderService,
    private cdr: ChangeDetectorRef,
    private authService: AuthService,

  ) {}

  get visibleColumns() {
    return this.columns.filter(column => column.visible).map(column => column.property);
  }

    hasPermission(permiso: string): boolean {
  return this.authService.hasPermission(permiso);
  }

  getRoles() {
    this.roleService.getRoles().subscribe({
      next: (data) => {
        this.subject$.next(data.message);
        console.log(data.message)
      },
      error: (err) => {
        console.error('Error al cargar roles', err);
      }
    });
  }

  ngOnInit() {
    this.getRoles();
    this.dataSource = new MatTableDataSource();

    this.data$.pipe(filter(data => !!data)).subscribe((roles) => {
      this.roles = roles;
      this.dataSource.data = roles;
    });
  }

  ngAfterViewInit() {
    this.dataSource.paginator = this.paginator;
    this.dataSource.sort = this.sort;
  }

  createRol() {
    this.dialog.open(RoleCreateUpdateComponent).afterClosed().subscribe((rol: Role) => {
      if (rol) {
        this.roles.unshift(rol);
        this.subject$.next(this.roles);
        this.getRoles();
      }
    });
  }

  updateRol(rol: Role) {
    this.dialog.open(RoleCreateUpdateComponent, { data: rol }).afterClosed().subscribe((updatedRol: Role) => {
      if (updatedRol) {
        const index = this.roles.findIndex(r => r.id_rol === updatedRol.id_rol);
        this.roles[index] = updatedRol;
        this.subject$.next(this.roles);
        this.getRoles();
      }
    });
  }

  deleteRol(rol: Role) {
    const confirmed = confirm(`¿Seguro que deseas eliminar el rol "${rol.name_rol}"?`);
    if (!confirmed) return;

    this.loader.show();

    this.roleService.eliminarRol(rol.id_rol).subscribe({
      next: () => {
        this.roles = this.roles.filter(r => r.id_rol !== rol.id_rol);
        this.subject$.next(this.roles);
        this.toast.success('Rol eliminado', `${rol.name_rol} fue eliminado correctamente`);
      },
      error: (err) => {
        this.toast.error('Error al eliminar rol', err?.error?.detail || 'No se pudo eliminar el rol');
      },
      complete: () => this.loader.hide()
    });
  }

  onFilterChange(value: string) {
    if (!this.dataSource) return;
    value = value.trim().toLowerCase();
    this.dataSource.filter = value;
  }
}
